using System;using System.Linq;using System.Threading.Tasks;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.SceneManagement;using Demo5.FrontEnd;
public static class VerifyGroupedHud {
 static async Task Tap(Button b){await Task.Delay(150);Canvas.ForceUpdateCanvases();if(!b.IsActive()||!b.IsInteractable())throw new Exception("Unavailable "+b.name);var r=(RectTransform)b.transform;var e=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(b.GetComponentInParent<Canvas>().worldCamera,r.TransformPoint(r.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(e,hits);if(hits.Count==0||hits[0].gameObject.GetComponentInParent<Button>()!=b)throw new Exception("Blocked "+b.name);ExecuteEvents.Execute(b.gameObject,e,ExecuteEvents.pointerClickHandler);await Task.Delay(150);}
 public static async Task<string> Load(){var c=UnityEngine.Object.FindAnyObjectByType<SettlementController>();CampaignSaveStore.TestDirectory=System.IO.Path.GetFullPath("Temp/OpeningChapterVerification");try{var saved=CampaignSaveStore.Read(0,c);if(!saved.CanLoad)throw new Exception(saved.Error);CampaignPersistence.Prepare(saved.Data,c);}finally{CampaignSaveStore.TestDirectory=null;}SceneManager.LoadScene("Settlement");await Task.Delay(650);return "Loaded isolated completed chapter fixture.";}
 public static async Task<string> Buttons(){var c=UnityEngine.Object.FindAnyObjectByType<SettlementController>();await Tap(c.Advance);await Tap(c.TimePanel.CloseButton);await Tap(c.CraftPanel.HousingButton);await Tap(c.CraftPanel.CloseButton);await Tap(c.Journal);await Tap(c.ReturnPanel.Back);await Tap(c.GameMenu.OpenButton);await Tap(c.GameMenu.Resume);string visitor="unavailable (schedule)";if(c.VisitorPanel.OpenButton.IsInteractable()){await Tap(c.VisitorPanel.OpenButton);await Tap(c.VisitorPanel.Back);visitor="clicked";}if(!c.Main.interactable)throw new Exception("HUD not restored");return "PASS raycast clicks: time, housing, journal, menu; visitor "+visitor+". Screen "+Screen.width+"x"+Screen.height;}
}
